-- AI-01--06 / ORG-040. Synthetic rollback only; no provider calls.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir ../support/registration-fixtures.psql
\ir ../support/abstract-fixtures.psql
\ir ../support/advisory-fixtures.psql
select is((select count(*) from msrc_abstracts.advisory_settings),0::bigint,'No advisory activation or operating values seeded');
select ok(not exists(select 1 from pg_class c where c.relnamespace='msrc_abstracts'::regnamespace and c.relname like 'advisory_%' and c.relkind='r' and not(c.relrowsecurity and c.relforcerowsecurity)),'Every advisory table forces RLS');
select ok(not exists(select 1 from pg_class c cross join(values('anon'),('authenticated'),('service_role')) r(name) where c.relnamespace='msrc_abstracts'::regnamespace and c.relname like 'advisory_%' and c.relkind='r' and has_table_privilege(name,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')),'No API role can directly access advisory tables');
select ok(not exists(select 1 from pg_policies where schemaname='msrc_abstracts' and tablename like 'advisory_%'),'No client-facing advisory policies');
select ok(not exists(select 1 from pg_proc p where p.pronamespace='public'::regnamespace and p.proname like '%advisory%' and p.prosecdef and not('search_path=""'=any(p.proconfig))),'Public advisory definers pin empty search path');
select ok(not exists(select 1 from pg_proc p cross join lateral aclexplode(p.proacl) a where p.pronamespace='public'::regnamespace and p.proname like 'msrc_advisory_worker_%' and a.grantee in(0,'anon'::regrole,'authenticated'::regrole)),'Worker functions are server-only');
select ok(not exists(select 1 from pg_proc p cross join lateral aclexplode(p.proacl) a where p.pronamespace='msrc_abstracts'::regnamespace and p.proname like 'advisory_%' and a.grantee in(0,'anon'::regrole,'authenticated'::regrole,'service_role'::regrole)),'Private advisory validators have no API execute ACL');
select is(msrc_abstracts.advisory_defaults()->>'enabled','false','Absent configuration disables scorer');
select is(msrc_abstracts.advisory_defaults()->>'reviewerVisible','false','Reviewer visibility defaults off');
select is(msrc_abstracts.advisory_defaults()->>'maxPerRun',null::text,'No invented run cap');
select is(msrc_abstracts.advisory_defaults()->>'estimatedCostPerAbstract',null::text,'No invented estimated price');
select ok(msrc_abstracts.advisory_configuration_valid(msrc_abstracts.advisory_defaults()),'Closed empty configuration valid');
select ok(not msrc_abstracts.advisory_configuration_valid(msrc_abstracts.advisory_defaults()||'{"enabled":true}'::jsonb),'Activation without gates refused');
select ok(msrc_abstracts.advisory_configuration_valid(pg_temp.advisory_configuration()),'Explicit synthetic configuration valid');
select ok(not msrc_abstracts.advisory_configuration_valid(pg_temp.advisory_configuration()||'{"noticeReference":null}'::jsonb),'Missing data handling notice refuses activation');
select ok(not msrc_abstracts.advisory_configuration_valid(pg_temp.advisory_configuration()||'{"evaluationReference":null}'::jsonb),'Missing evaluation refuses activation');
select ok(not msrc_abstracts.advisory_configuration_valid(pg_temp.advisory_configuration()||'{"operatingReference":null}'::jsonb),'Missing operating evidence refuses activation');
select ok(not msrc_abstracts.advisory_configuration_valid(pg_temp.advisory_configuration()||'{"dailyCostCap":0.5}'::jsonb),'At least one full retry reservation must fit the cost cap');
select ok(not msrc_abstracts.advisory_configuration_valid(pg_temp.advisory_configuration()||'{"maxPerRun":21}'::jsonb),'Run cap cannot exceed day cap');
select ok(not msrc_abstracts.advisory_configuration_valid(pg_temp.advisory_configuration()||'{"maxPerRun":1.5}'::jsonb),'Fractional abstract budget rejected');
select ok(not msrc_abstracts.advisory_configuration_valid(pg_temp.advisory_configuration()||'{"model":"invented"}'::jsonb),'Unapproved model rejected');
select ok(msrc_abstracts.advisory_result_valid(pg_temp.advisory_output(),pg_temp.abstract_settings()->'rubric','deepseek-flash'),'Strict valid synthetic output accepted');
select ok(not msrc_abstracts.advisory_result_valid(pg_temp.advisory_output()||'{"decision":"accept"}'::jsonb,pg_temp.abstract_settings()->'rubric','deepseek-flash'),'Outcome field discarded as invalid output');
select ok(not msrc_abstracts.advisory_result_valid(jsonb_set(pg_temp.advisory_output(),'{scores,0,value}','9'::jsonb),pg_temp.abstract_settings()->'rubric','deepseek-flash'),'Out-of-range score rejected');
select ok(not msrc_abstracts.advisory_result_valid(jsonb_set(pg_temp.advisory_output(),'{scores,0,criterionId}','"unknown"'::jsonb),pg_temp.abstract_settings()->'rubric','deepseek-flash'),'Unknown criterion rejected');
select ok(not msrc_abstracts.advisory_result_valid(jsonb_set(pg_temp.advisory_output(),'{scores,0,rationale}','""'::jsonb),pg_temp.abstract_settings()->'rubric','deepseek-flash'),'Empty rationale rejected');
select ok(not msrc_abstracts.advisory_result_valid(pg_temp.advisory_output()||'{"scores":[]}'::jsonb,pg_temp.abstract_settings()->'rubric','deepseek-flash'),'Incomplete criteria rejected');
select ok(not msrc_abstracts.advisory_result_valid(pg_temp.advisory_output(),pg_temp.abstract_settings()->'rubric','another-model'),'Model mismatch rejected');
set local role anon;
select throws_ok($$select public.msrc_staff_advisory_workspace('synthetic-advisory')$$,'42501',null,'Anonymous cannot read staff advisory');
reset role;
set local role authenticated;
select throws_ok($$select public.msrc_advisory_worker_claim(gen_random_uuid(),1)$$,'42501',null,'Authenticated clients cannot claim jobs');
select throws_ok($$select public.msrc_advisory_worker_finish(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null,'provider_unavailable')$$,'42501',null,'Authenticated clients cannot complete jobs');
reset role;
select is(public.msrc_advisory_worker_claim(gen_random_uuid(),1),'[]'::jsonb,'No settings means no provider work');

update msrc_participant.policy set enabled=true,privacy_version='synthetic-registration-notice',email_daily_limit=1000;
update msrc_participant.retention_policy set enabled=true;
update msrc_staff.policy set enabled=true,email_daily_limit=1000;
insert into msrc_authorization.edition_config(edition_key) values('synthetic-advisory');
select pg_temp.registration_fixture(9704,'synthetic-advisory');
select pg_temp.registration_staff_fixture(9700,'synthetic-advisory');
select pg_temp.registration_staff_fixture(9701,'synthetic-advisory','scientificAdministrator');
select pg_temp.registration_staff_fixture(9702,'synthetic-advisory','abstractReviewer');
select pg_temp.registration_staff_fixture(9703,'synthetic-advisory','finance');
select pg_temp.abstract_claims(9700);
select is(public.msrc_staff_research_save_settings('synthetic-advisory',0,pg_temp.abstract_settings())->>'state','ready','Synthetic rubric configured without opening abstracts');
select pg_temp.advisory_submission(n,'synthetic-advisory',9704) from generate_series(1,6) n;
select is(public.msrc_staff_advisory_workspace('synthetic-advisory')->>'eligibleCount','6','Only finalized prepared-packet candidates projected');
select is(public.msrc_staff_advisory_start('synthetic-advisory',pg_temp.advisory_id(101),array[pg_temp.advisory_id(1)])->>'state','disabled','Default-off DB gate refuses enqueue');
select is(public.msrc_staff_advisory_save_settings('synthetic-advisory',0,msrc_abstracts.advisory_defaults())->>'state','updated','SA can save closed draft configuration');
select pg_temp.abstract_claims(9701);
select is(public.msrc_staff_advisory_save_settings('synthetic-advisory',1,pg_temp.advisory_configuration())->>'state','denied','Science cannot activate or approve gate evidence');
select is(public.msrc_staff_advisory_save_settings('synthetic-advisory',1,msrc_abstracts.advisory_defaults()||'{"maxPerRun":2,"maxPerDay":20,"estimatedCostPerAbstract":0.5,"dailyCostCap":5,"currency":"USD"}'::jsonb)->>'state','updated','Science may explicitly configure budget');
select pg_temp.abstract_claims(9703);
select is(public.msrc_staff_advisory_workspace('synthetic-advisory')->>'state','denied','Finance denied staff advisory');
select is(public.msrc_staff_advisory_calibration('synthetic-advisory')->>'state','denied','Finance denied calibration');
select pg_temp.abstract_claims(9704);
select is(public.msrc_staff_advisory_workspace('synthetic-advisory')->>'state','denied','Author cannot read advisory workspace');
select is(public.msrc_staff_advisory_calibration('synthetic-advisory')->>'state','denied','Author cannot infer advisory via calibration');
select is(public.msrc_staff_advisory_reviewer('synthetic-advisory',gen_random_uuid())->>'state','denied','Author cannot use reviewer projection');
select pg_temp.abstract_claims(9700);
select is(public.msrc_staff_advisory_save_settings('synthetic-advisory',1,pg_temp.advisory_configuration())->>'state','conflict','Settings compare-and-swap rejects stale configuration');
select is(public.msrc_staff_advisory_save_settings('synthetic-advisory',2,pg_temp.advisory_configuration())->>'state','updated','Synthetic assured SA can explicitly activate with all evidence');
select pg_temp.abstract_claims(9701);
select is(public.msrc_staff_advisory_start('synthetic-advisory',pg_temp.advisory_id(100),array[pg_temp.advisory_id(2),pg_temp.advisory_id(3),pg_temp.advisory_id(4)])->>'state','budget_exceeded','Run cap checked server-side');
select is(public.msrc_staff_advisory_start('synthetic-advisory',pg_temp.advisory_id(100),array[pg_temp.advisory_id(1),pg_temp.advisory_id(1)])->>'state','invalid','Duplicate IDs rejected before billing');
create temporary table advisory_result(key text primary key,value jsonb);
insert into advisory_result values('run1',public.msrc_staff_advisory_start('synthetic-advisory',pg_temp.advisory_id(101),array[pg_temp.advisory_id(1)]));
select is((select value->>'state' from advisory_result where key='run1'),'queued','Science can enqueue an explicitly budgeted finalized abstract');
select is(public.msrc_staff_advisory_start('synthetic-advisory',pg_temp.advisory_id(101),array[pg_temp.advisory_id(1)])->>'runId',(select value->>'runId' from advisory_result where key='run1'),'Operation retry returns same durable run');
select is(public.msrc_staff_advisory_start('synthetic-advisory',pg_temp.advisory_id(102),array[pg_temp.advisory_id(1)])->>'state','conflict','Different operation cannot rescore same abstract and rubric');
select is((select reserved_abstracts from msrc_abstracts.advisory_daily_usage where edition_key='synthetic-advisory'),1,'Idempotent retries consume no extra reservation');
select is((select reserved_cost from msrc_abstracts.advisory_daily_usage where edition_key='synthetic-advisory'),1::numeric,'Reserve all possible attempts at enqueue');
insert into advisory_result values('claim1',public.msrc_advisory_worker_claim(pg_temp.advisory_id(900),1));
select is(jsonb_array_length((select value from advisory_result where key='claim1')),1,'Worker leases one small chunk');
select ok((select value::text !~ 'Identity Canary|example.invalid|affiliations|ethics|keywords|specialtyId|studyTypeId|completionStatus' from advisory_result where key='claim1'),'Worker payload excludes identities, account fields and unrelated scientific metadata');
select is((select value->0->'body' from advisory_result where key='claim1'),pg_temp.abstract_packet()->'body','Worker receives only sanitized scientific body');
select is(public.msrc_advisory_worker_claim(pg_temp.advisory_id(901),1),'[]'::jsonb,'Second worker cannot take active lease');
select is(public.msrc_advisory_worker_finish(pg_temp.advisory_id(901),(select (value->0->>'id')::uuid from advisory_result where key='claim1'),(select (value->0->>'leaseToken')::uuid from advisory_result where key='claim1'),pg_temp.advisory_output(),null)->>'state','stale','Wrong worker cannot finish');
select is(public.msrc_advisory_worker_finish(pg_temp.advisory_id(900),(select (value->0->>'id')::uuid from advisory_result where key='claim1'),(select (value->0->>'leaseToken')::uuid from advisory_result where key='claim1'),pg_temp.advisory_output(),null)->>'state','completed','Validated advisory retained separately');
select is(public.msrc_advisory_worker_finish(pg_temp.advisory_id(900),(select (value->0->>'id')::uuid from advisory_result where key='claim1'),(select (value->0->>'leaseToken')::uuid from advisory_result where key='claim1'),pg_temp.advisory_output(),null)->>'state','stale','Repeated completion cannot duplicate result');
select is((select count(*) from msrc_abstracts.advisory_records),1::bigint,'One immutable advisory record');
select is((select count(*) from msrc_abstracts.decisions),0::bigint,'Advisory never creates a decision');
select is((select count(*) from msrc_abstracts.assignments),0::bigint,'Advisory never creates or modifies a human scorecard');
select throws_ok($$update msrc_abstracts.advisory_records set scores='[]'::jsonb$$,'55000',null,'Advisory results are immutable');
select ok(public.msrc_staff_advisory_workspace('synthetic-advisory')->'runs' @> '[{"completed":1,"failed":0,"pending":0}]'::jsonb,'Run log reports counts');
select ok((public.msrc_staff_advisory_workspace('synthetic-advisory')->'runs')::text !~ 'rationale|Synthetic study|scores|prompt','Run logs contain no prompts or provider outputs');
insert into msrc_abstracts.reviewer_profiles values('synthetic-advisory',pg_temp.registration_actor(9702),array['Independent synthetic institute']);
insert into msrc_abstracts.assignments(id,edition_key,submission_id,submission_version,rubric_version,reviewer_id,status)
 values(pg_temp.advisory_id(800),'synthetic-advisory',pg_temp.advisory_id(1),1,1,pg_temp.registration_actor(9702),'assigned');
select pg_temp.abstract_claims(9702);
select is(public.msrc_staff_advisory_reviewer('synthetic-advisory',pg_temp.advisory_id(800))->'advisory','null'::jsonb,'Assigned reviewer cannot see AI with default visibility');
select is(public.msrc_staff_advisory_workspace('synthetic-advisory')->>'state','denied','Reviewer cannot use administrator workspace');
select pg_temp.abstract_claims(9700);
select is(public.msrc_staff_advisory_save_settings('synthetic-advisory',3,pg_temp.advisory_configuration()||'{"reviewerVisible":true}'::jsonb)->>'state','updated','Only SA can permit reviewer visibility');
select pg_temp.abstract_claims(9702);
select is(public.msrc_staff_advisory_reviewer('synthetic-advisory',pg_temp.advisory_id(800))->'advisory','null'::jsonb,'Permission alone cannot anchor an unscored reviewer');
update msrc_abstracts.assignments set status='completed',scorecard='{"scores":[{"criterionId":"synthetic-criterion","value":3}],"comments":"Independent reasoning","recommendation":"revise"}'::jsonb,score_total=33.333 where id=pg_temp.advisory_id(800);
select is(public.msrc_staff_advisory_reviewer('synthetic-advisory',pg_temp.advisory_id(800))->'advisory'->'scores'->0->>'value','4','Independent reviewer with explicit SA visibility can read separate suggestion');
select pg_temp.abstract_claims(9701);
select is(public.msrc_staff_advisory_calibration('synthetic-advisory')->'pairs'->0->>'aiScore','4','Calibration returns advisory score');
select is(public.msrc_staff_advisory_calibration('synthetic-advisory')->'pairs'->0->>'humanScore','3.0000000000000000','Calibration uses independent completed human criterion');
select is((select scorecard->'scores'->0->>'value' from msrc_abstracts.assignments where id=pg_temp.advisory_id(800)),'3','Reading suggestion leaves human score unchanged');

select is(public.msrc_staff_advisory_start('synthetic-advisory',pg_temp.advisory_id(102),array[pg_temp.advisory_id(2)])->>'state','queued','Second test abstract queued');
insert into advisory_result values('claim2',public.msrc_advisory_worker_claim(pg_temp.advisory_id(900),1));
select is(public.msrc_advisory_worker_finish(pg_temp.advisory_id(900),(select (value->0->>'id')::uuid from advisory_result where key='claim2'),(select (value->0->>'leaseToken')::uuid from advisory_result where key='claim2'),pg_temp.advisory_output()||'{"decision":"accept"}'::jsonb,null)->>'state','failed','Invalid response discarded without retry');
select is((select count(*) from msrc_abstracts.advisory_records),1::bigint,'Invalid output never persisted');
select is(public.msrc_staff_advisory_start('synthetic-advisory',pg_temp.advisory_id(103),array[pg_temp.advisory_id(3)])->>'state','queued','Retry test queued');
insert into advisory_result values('claim3',public.msrc_advisory_worker_claim(pg_temp.advisory_id(900),1));
select is(public.msrc_advisory_worker_finish(pg_temp.advisory_id(900),(select (value->0->>'id')::uuid from advisory_result where key='claim3'),(select (value->0->>'leaseToken')::uuid from advisory_result where key='claim3'),null,'provider_unavailable')->>'state','retry','Transient provider error schedules bounded retry');
select ok((select next_attempt_at>clock_timestamp() from msrc_abstracts.advisory_jobs where submission_id=pg_temp.advisory_id(3)),'Retry has backoff');
select is(public.msrc_advisory_worker_claim(pg_temp.advisory_id(901),1),'[]'::jsonb,'Backoff cannot be bypassed by another worker');
update msrc_abstracts.advisory_jobs set next_attempt_at=clock_timestamp()-interval '1 second' where submission_id=pg_temp.advisory_id(3);
insert into advisory_result values('retry3',public.msrc_advisory_worker_claim(pg_temp.advisory_id(901),1));
select is((select value->0->>'attempt' from advisory_result where key='retry3'),'2','Retry records another attempt');
select is(public.msrc_advisory_worker_finish(pg_temp.advisory_id(900),(select (value->0->>'id')::uuid from advisory_result where key='claim3'),(select (value->0->>'leaseToken')::uuid from advisory_result where key='claim3'),pg_temp.advisory_output(),null)->>'state','stale','Old lease cannot commit after retry');
select is(public.msrc_advisory_worker_finish(pg_temp.advisory_id(901),(select (value->0->>'id')::uuid from advisory_result where key='retry3'),(select (value->0->>'leaseToken')::uuid from advisory_result where key='retry3'),null,'rate_limited')->>'state','failed','Configured attempt limit ends retry loop');
select is((select attempt_count from msrc_abstracts.advisory_daily_usage where edition_key='synthetic-advisory'),4,'Retries consume current-day dispatch budget');
select is(public.msrc_staff_advisory_start('synthetic-advisory',pg_temp.advisory_id(104),array[pg_temp.advisory_id(4),pg_temp.advisory_id(5)])->>'state','queued','Remaining reservation capacity accepted');
select is(public.msrc_staff_advisory_start('synthetic-advisory',pg_temp.advisory_id(106),array[pg_temp.advisory_id(6)])->>'state','budget_exceeded','Daily estimated-cost reservation cannot be overspent');
insert into advisory_result values('claim45',public.msrc_advisory_worker_claim(pg_temp.advisory_id(900),2));
select is(jsonb_array_length((select value from advisory_result where key='claim45')),2,'Small batch processes independent jobs');
select pg_temp.abstract_claims(9700);
select is(public.msrc_staff_advisory_save_settings('synthetic-advisory',4,pg_temp.advisory_configuration()||'{"enabled":false,"reviewerVisible":true}'::jsonb)->>'state','updated','SA may disable while work is in flight');
select is(public.msrc_advisory_worker_finish(pg_temp.advisory_id(900),(select (value->0->>'id')::uuid from advisory_result where key='claim45'),(select (value->0->>'leaseToken')::uuid from advisory_result where key='claim45'),pg_temp.advisory_output(),null)->>'state','failed','Disable invalidates an in-flight response');
select is(public.msrc_advisory_worker_claim(pg_temp.advisory_id(902),1),'[]'::jsonb,'Disabled database issues no new lease');
select is((select count(*) from msrc_abstracts.advisory_records),1::bigint,'No new advisory committed after disable');
select pg_temp.abstract_claims(9704);
select ok(public.msrc_abstracts_me('synthetic-advisory',pg_temp.registration_claims(9704))::text !~ 'advisory|rationale|deepseek|promptVersion','Participant projection contains no AI results');
select * from finish();
rollback;
